/**
 * Get rules by their scopes.
 * @param scope {string} The scope name of the rules object.
 * @returns {{}|*}
 */
function getFlattenedRules(...scope) {
    return scope.map(n => Object.hasOwn(RULES, n) ? RULES[n] : {}).reduce((acc, curr) => ({ ...acc, ...curr }), {});
}

