            "typescript/default-param-last": "error",
            "typescript/dot-notation": ["warn", { allowPrivateClassPropertyAccess: true }],
            "typescript/explicit-function-return-type": ["warn", { allowExpressions: true, allowTypedFunctionExpressions: true, allowHigherOrderFunctions: true }],
            "typescript/explicit-member-accessibility": ["warn", { accessibility: "explicit", overrides: { constructors: "no-public" } }],
            "typescript/explicit-module-boundary-types": ["warn", { allowArgumentsExplicitlyTypedAsAny: true, allowDirectConstAssertionInArrowFunctions: true }],
            "typescript/init-declarations": "off",
